create table if not exists public.client_credentials ( id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients (id) on delete cascade, platform text not null check (char_length(btrim(platform)) between 1 and 40), label text check (label is null or char_length(label) <= 60), username text check (username is null or char_length(username) <= 200), url text check (url is null or char_length(url) <= 500), secret_cipher text check (secret_cipher is null or secret_cipher ~ '^v[0-9]+\.'), notes_cipher text check (notes_cipher is null or notes_cipher ~ '^v[0-9]+\.'), key_id text check (key_id is null or char_length(key_id) <= 32), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references public.profiles (id) on delete set null ); create index if not exists client_credentials_client_idx on public.client_credentials (client_id, platform, label); alter table public.client_credentials enable row level security; drop policy if exists "client_credentials: management" on public.client_credentials; create policy "client_credentials: management" on public.client_credentials for all using (public.can_manage_client(client_id)) with check (public.can_manage_client(client_id)); drop policy if exists "client_credentials: staff assigned" on public.client_credentials; create policy "client_credentials: staff assigned" on public.client_credentials for all using (public.current_role() = 'staff' and public.is_assigned_staff(client_id)) with check (public.current_role() = 'staff' and public.is_assigned_staff(client_id)); drop trigger if exists client_credentials_touch_updated_at on public.client_credentials; create trigger client_credentials_touch_updated_at before update on public.client_credentials for each row execute procedure public.touch_updated_at();
